Method.Implementation:
#dim tSC As %Status = $$$OK
 NEW $NAMESPACE
 try {
 	set $NAMESPACE = nmSp
 } catch err
 {
	 return "Invalid namespace: " _ nmSp _ err.Name _ " " _ err.Code

 }
 Do ##class(ITFCOMMON.Utility).WriteToFile( "NAMESPACE: " _ $NAMESPACE) 
 try
 {
  set ..DeployDirectory = $$$USRRELEASEBASEDIR _ userNm _ $$$SVNSRCTRUNK
 } catch err
 {
	 Do ##class(ITFCOMMON.Utility).WriteToFile( "Error: " _ err.Name _ " " _ err.Data _ " " _ ..DeployDirectory)
 }


 set tProductionName = ##class(Ens.Director).GetActiveProductionName()

 if tProductionName = ""
 {
  Do ##class(ITFCOMMON.Utility).WriteToFile( "Could not get active production in " _ $NAMESPACE)
  return "Active production not found in " _ $NAMESPACE
 }
 Do ##class(ITFCOMMON.Utility).WriteToFile( "Active PROD: " _ tProductionName)


 set env = "Dev"

 if $$$ISERR( ##class(ITFCOMMON.SrcCtrlPkg.ItfSrcCtrlUtil).DoSvnSetup(userNm, passwd))
 {
	 return "ERROR in SVN"
 }

 Set tExportFilename = ..DeployDirectory_"Deployment_CONFIG_" _tItemName_".xml"

 Do ..CreateComment(tItemName)

 set tSC = ..CreateConfigFile(tItemName, tExportFilename, tProductionName)
 if $$$ISERR(tSC)
 {
	 Set comment =  ##class(ITFCOMMON.Utility).getErrorMsg(tSC, "Config file create failed. ")
	 return comment
 }
 else
 {
 	Set tExportClsFilename = ..DeployDirectory_"Deployment_CLS_"_tItemName_".xml"
 	set tSC = ..CreateClassFile(tItemName,  tExportClsFilename, nmSp, tProductionName, userNm, passwd) 
 }
 if $$$ISERR(tSC)
 {
	 Do ##class(ITFCOMMON.Utility).WriteToFile( "Class file was not created. ")
	 if tSC [ "No Classes to expo"
	 {
		 set tExportClsFilename = ""
	 }
	 else
	 {
		Set comment = ##class(ITFCOMMON.Utility).getErrorMsg(tSC, "Class file create failed. ")
	 	return comment
	 }
 }
 Do ..tComments.Rewind()
 set len = 32656
 #dim sc as %Status
 set comment = ..tComments.Read(.len, .sc)
 set commitComment = ""
 if $$$ISOK(sc)
 {
 	set tSC = ..CheckinFiles(tExportFilename _ " " _ tExportClsFilename, userNm, passwd, comment, .commitComment)
 }
 else
 {
	Do ##class(ITFCOMMON.Utility).WriteToFile( "Error in reading comments" )
 }
 if $$$ISERR(tSC)
 {
	 Set comment =  ##class(ITFCOMMON.Utility).getErrorMsg(tSC, "Could not create files. ")
 }

 return commitComment _ comment



 Do ..tComments.Rewind()

 Set:(tItemName '[ "||") tItemName = tProductionName_"||"_tItemName

	Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(tItemName)
	If ' $IsObject(tItem)
	{
		Quit $$$ERROR($$$EnsErrGeneral, "Can't open object: " _tItemName )
	}

	Do ##class(ITFCOMMON.Utility).WriteToFile( tItemName _" is valid in " _ tProductionName)
	Set tSC=##class(%Studio.Project).Delete(..tProjectName) 
	Set tSC = ##class(Ens.Deployment.Utils).CreatePTDFromItem(.tItem,.tPTDName)	
	If tPTDName '= "" 
	{
		     //Create Deployment file with PTDs	
		     // Do ##class(ITFCOMMON.Utility).WriteToFile( 	tPTDName  )    	
		   Set tContentsList(tPTDName_".PTD")=""

		   Set tSC =##class(Ens.Deployment.Utils).CreateExportPackageFromProjectList(..tProjectName,.tContentsList,tExportFilename,tProductionName,..tComments,..tProductionClassIncluded)
		   if $$$ISERR(tSC)
		   {
			   Do ##class(ITFCOMMON.Utility).WriteToFile( "Failed to Export: " _ tSC)
			   SET tSC =  $$$ERROR($$$EnsErrGeneral, "Failed to create ExportPackage file")
		   }
		   else
		   {
		   		Do ##class(ITFCOMMON.Utility).WriteToFile( "Created export file: " _ tExportFilename)
		   }
		   Do ##class(Ens.Util.ProjectTextDocument).Delete(tPTDName_".PTD")

	}
	else
	{
		SET tSC =  $$$ERROR($$$EnsErrGeneral, "Failed to create PTDFromItem")
	}
	Quit tSC


 Do ..tComments.MoveToEnd()

 Set:(tItemName '[ "||") tItemName = tProductionName_"||"_tItemName

 Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(tItemName)
 If ' $IsObject(tItem)
 {
	Quit $$$ERROR($$$EnsErrGeneral, "Can't open object: " _tItemName )
 }

 // Open production and get items for the component
 Set tProduction = ##class(Ens.Config.Production).%OpenId(tProductionName,,.tSC)
 Set tSC=tProduction.getProjectArrayFromConfigItem(tItem,.tProjectArray) 
   // Do ##class(ITFCOMMON.Utility).WriteToFile( "getProjectArrayFromConfigItem: " _ tSC)
 Quit:$$$ISERR(tSC) tSC

 Set tSC=tProduction.expandProjectArray(.tProjectArray)  Quit:$$$ISERR(tSC) tSC
 // Do ##class(ITFCOMMON.Utility).WriteToFile( "expandProjectArray " _ tSC)
 Quit:$$$ISERR(tSC) tSC

 set tSC = tProduction.createStudioProjectFromArray(.tProject,.tProjectArray, ..tProjectName, "DESC")
  // Do ##class(ITFCOMMON.Utility).WriteToFile( "createStudioProjectFromArray " _ tSC)
 set num =1
 Set k=""  
 For 
  { 
	   #dim tItem As %Studio.ProjectItem 
		Set tItem=tProject.Items.GetNext(.k)  Quit:""=k||'$IsObject(tItem)
		Set tItemName=tItem.Name

		if '(tItemName [ "ITFCOMMON")
		{


		Do ##class(ITFCOMMON.Utility).WriteToFile( userNm _ " : " _ num _". " _ tItemName _ " = " _  tItem.Type)

		// Does the Name end with type
		if $F(tItemName, tItem.Type) >  $L(tItemName)
		{
			set item = tItemName
	 	}
	 	else
	 	{
			set item = tItemName _ "." _ tItem.Type
	 	}

	 	if item [ "CLS"
	 	{

	 			set tSC = ..CheckItemWithSrcCtrl(item,  userNm, passwd)

	 			if $$$ISERR(tSC)
	 			{
		 			Return tSC 
	 			}

	 	}

	  	Set tFullList(item)=""


		// Export each item to file
		// set fileNm = "/home/lpjnaras/EnsExport/" _ item
		// Set sc=$$Export^%occXMLExport(fileNm,"-d /diffexport",item)

	   	set num = num + 1
		}
	}
	if (num > 1)
	{
       Do ..tComments.Rewind()

       	Set tSC =##class(Ens.Deployment.Utils).CreateExportPackageFromProjectList(..tProjectName,.tFullList,tExportClsFilename,tProductionName,..tComments,..tProductionClassIncluded)
       	if $$$ISERR(tSC)
   		{
	   		Do ##class(ITFCOMMON.Utility).WriteToFile( "Failed to Export: " _ tSC)
	   		QUIT tSC
   		}


	}
	else
	{
		set tSC = $$$ERROR($$$EnsErrGeneral, "No Classes to export")
		Quit tSC
	}

	if ##class(%File).Exists(tExportClsFilename)
	{
		Do ##class(ITFCOMMON.Utility).WriteToFile( "Created Class file: " _ tExportClsFilename)
	}
	else
	{
		Do ##class(ITFCOMMON.Utility).WriteToFile( "CLASS file NOT EXPORTED")
	}


	Quit tSC

#dim tSC As %Status
set tSC = $$$OK

if ##class(%RoutineMgr).Exists(itemNm)
{

	set extNm = ##class(ITFCOMMON.SrcCtrlPkg.ItfSrcCtrlUtil).ExternalName(itemNm, userNm)
	if ##class(%File).Exists(extNm)
	{
	       // found file, get time and SVN information
		   set fileModTm = ##class(%File).GetFileDateModified(extNm)
		   //Get internal time	
		   set intTime= $ZDATETIMEH(##class(%RoutineMgr).TS(itemNm), 3, 1)
		   Do ##class(ITFCOMMON.Utility).WriteToFile("TIME: " _ itemNm _ ": " _ intTime _ ", file: " _ extNm _ " " _ fileModTm)

		   set ddIntTime = $P(intTime, ",", 1)
		   set ddFileModTm = $P(fileModTm, ",", 1)
		   set tmIntTime = $P(intTime, ",", 2)
		   set tmFileModTm = $P(fileModTm, ",", 2)
		   if ( (ddIntTime) > (ddFileModTm) )
		   {
			   	Do ##class(ITFCOMMON.Utility).WriteToFile( " !!! Internal time is later than Checkin time")
			   	set tSC = $$$ERROR($$$EnsErrGeneral, "Internal time is later than Checkin time : " _ itemNm)

		   }
		   elseif ( ((ddIntTime) = (ddFileModTm)) &&  (tmIntTime > tmFileModTm))
		   {
			   	Do ##class(ITFCOMMON.Utility).WriteToFile( " !!! Internal time is later than Checkin time")
			  	set tSC = $$$ERROR($$$EnsErrGeneral, "Internal time is later than Checkin time : " _ itemNm)

		   }
		   else
		   {
		   	set tSC = ..getCommentForFile(itemNm, extNm, userNm, passwd)
		   } 		
	  }
	  else
	  {
	   		Do ##class(ITFCOMMON.Utility).WriteToFile( " !!! File not in source control: " _ extNm)
	   		set tSC = $$$ERROR($$$EnsErrGeneral, "File not in source control: " _ extNm)
	  }
}
Quit tSC
